import os,pathlib,tempfile,stat,secrets,json,hashlib,time
def receive(parent,start,budget):
    if type(budget) not in (int,float) or not .05<=budget<=2:raise ValueError('bounded FIFO session')
    parent=pathlib.Path(parent);meta=parent.stat(follow_symlinks=False)
    if not stat.S_ISDIR(meta.st_mode) or meta.st_uid!=os.geteuid() or meta.st_mode&0o077:raise ValueError('private parent')
    directory=pathlib.Path(tempfile.mkdtemp(prefix='of-fifo-',dir=parent));fifo=directory/'stream';fd=None;process=None;identity=None
    try:
        directory.chmod(0o700);os.mkfifo(fifo,0o600);identity=fifo.stat();fd=os.open(fifo,os.O_RDONLY|os.O_NONBLOCK)
        nonce=secrets.token_hex(16);deadline=time.monotonic()+budget;process=start(fifo,nonce)
        if process is None:raise RuntimeError('not_started')
        stage=0;rows=[];buffer=b''
        while True:
            try:chunk=os.read(fd,65536)
            except BlockingIOError:chunk=None
            if chunk:
                buffer+=chunk
                if len(buffer)>131072:raise RuntimeError('incomplete')
                while b'\n' in buffer:
                    line,buffer=buffer.split(b'\n',1)
                    try:message=json.loads(line.decode('utf8'))
                    except (ValueError,UnicodeDecodeError) as error:raise RuntimeError('incomplete') from error
                    if not isinstance(message,dict):raise RuntimeError('incomplete')
                    if stage==0:
                        if message!={'type':'hello','session':nonce}:raise RuntimeError('incomplete')
                        stage=1
                    elif stage==1 and message.get('type')=='row':
                        if set(message)!={'type','value'} or not isinstance(message['value'],str) or len(message['value'])>256 or len(rows)>=100:raise RuntimeError('incomplete')
                        rows.append(message['value'])
                    elif stage==1 and message.get('type')=='end':
                        digest=hashlib.sha256(json.dumps(rows,ensure_ascii=False,separators=(',',':')).encode()).hexdigest()
                        if set(message)!={'type','count','sha256'} or type(message['count']) is not int or message['count']!=len(rows) or message['sha256']!=digest:raise RuntimeError('incomplete')
                        stage=2
                    else:raise RuntimeError('incomplete')
            elif chunk==b'' and process.poll() is not None:
                if process.returncode==0 and stage==2 and not buffer:return rows
                raise RuntimeError('incomplete')
            if time.monotonic()>=deadline:raise TimeoutError('FIFO session deadline')
            time.sleep(.005)
    finally:
        if process is not None:
            if process.poll() is None:process.kill()
            process.wait(timeout=1)
        if fd is not None:os.close(fd)
        if identity is not None and fifo.exists() and (fifo.stat().st_dev,fifo.stat().st_ino)==(identity.st_dev,identity.st_ino):fifo.unlink()
        directory.rmdir()
